import React, { useState, useEffect, useCallback } from 'react';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';

/* ════════════════════════════════════════════════
   HELPERS
════════════════════════════════════════════════ */
function Stars({ value, size = 18, interactive = false, onChange }) {
  const [hover, setHover] = useState(0);
  const v = parseFloat(value) || 0;
  return (
    <div style={{ display: 'inline-flex', gap: 3 }}>
      {[1,2,3,4,5].map(i => (
        <span
          key={i}
          onClick={() => interactive && onChange?.(i)}
          onMouseEnter={() => interactive && setHover(i)}
          onMouseLeave={() => interactive && setHover(0)}
          style={{
            fontSize: size, cursor: interactive ? 'pointer' : 'default',
            color: i <= (hover || Math.round(v)) ? '#f59e0b' : 'rgba(255,255,255,0.15)',
            transition: 'all .15s', transform: interactive && i <= (hover || v) ? 'scale(1.15)' : 'scale(1)',
            display: 'inline-block',
          }}
        >★</span>
      ))}
    </div>
  );
}

function ModeBadge({ mode }) {
  const cfg = {
    en_ligne:   { icon: '🌐', label: 'En ligne',   color: '#38bdf8', bg: 'rgba(56,189,248,0.15)'  },
    presentiel: { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.15)'  },
    les_deux:   { icon: '🔀', label: 'Les deux',   color: '#6c63ff', bg: 'rgba(108,99,255,0.15)' },
  }[mode] || { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.15)' };
  return (
    <span style={{ display:'inline-flex', alignItems:'center', gap:5, fontSize:'.73rem', fontWeight:700, padding:'4px 11px', borderRadius:20, background:cfg.bg, color:cfg.color }}>
      {cfg.icon} {cfg.label}
    </span>
  );
}

function fmt(str) {
  if (!str) return '';
  return new Date(str + 'T00:00:00').toLocaleDateString('fr-FR', { weekday:'short', day:'numeric', month:'short' });
}

/* ════════════════════════════════════════════════
   MODAL WRAPPER
════════════════════════════════════════════════ */
function ModalOverlay({ onClose, children }) {
  useEffect(() => {
    const onKey = e => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => { window.removeEventListener('keydown', onKey); document.body.style.overflow = ''; };
  }, [onClose]);

  return (
    <div
      style={{ position:'fixed', inset:0, background:'rgba(0,0,0,0.75)', backdropFilter:'blur(8px)', zIndex:1000, display:'flex', alignItems:'center', justifyContent:'center', padding:16 }}
      onClick={e => e.target === e.currentTarget && onClose()}
    >
      <div style={{ background:'var(--surface)', borderRadius:28, width:'100%', maxWidth:720, maxHeight:'90vh', overflow:'hidden', display:'flex', flexDirection:'column', boxShadow:'0 40px 120px rgba(0,0,0,0.6)', border:'1px solid var(--border)', animation:'modalIn .25s cubic-bezier(.34,1.56,.64,1)' }}>
        <style>{`@keyframes modalIn{from{opacity:0;transform:scale(.92) translateY(20px)}to{opacity:1;transform:scale(1) translateY(0)}}`}</style>
        {children}
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   COMPOSANT PRINCIPAL
════════════════════════════════════════════════ */
export default function ProfModal({ prof, onClose }) {
  const { user } = useAuth();
  const [tab, setTab]                   = useState('profil');
  const [avis, setAvis]                 = useState([]);
  const [avisStats, setAvisStats]       = useState(null);
  const [dispos, setDispos]             = useState([]);
  const [monAvis, setMonAvis]           = useState(null);
  const [step, setStep]                 = useState(null); // null | 'choix_dispo' | 'confirmation'
  const [selectedDispo, setSelectedDispo] = useState(null);
  const [modeChoisi, setModeChoisi]     = useState(null);
  const [notes, setNotes]               = useState('');
  const [submitting, setSubmitting]     = useState(false);
  const [reservationFaite, setReservationFaite] = useState(null);

  // Avis form
  const [noteForm, setNoteForm]         = useState(0);
  const [commentForm, setCommentForm]   = useState('');
  const [sendingAvis, setSendingAvis]   = useState(false);
  const [avisSuccess, setAvisSuccess]   = useState(false);

  const profId   = prof.prof_id || prof.id;
  const profNom  = `${prof.user_prenom || ''} ${prof.user_nom || ''}`.trim() || 'Professeur';
  const profMode = prof.mode_enseignement || 'presentiel';

  /* ── Chargement données ── */
  const loadAvis = useCallback(() => {
    Promise.all([
      api.get(`/api/avis/professeur/${profId}`),
      api.get(`/api/avis/professeur/${profId}/stats`),
      user?.role === 'étudiant' ? api.get(`/api/avis/mon-avis/${profId}`).catch(() => ({ data: null })) : Promise.resolve({ data: null }),
    ]).then(([r1, r2, r3]) => {
      setAvis(r1.data || []);
      setAvisStats(r2.data);
      if (r3.data) {
        setMonAvis(r3.data);
        setNoteForm(r3.data.note);
        setCommentForm(r3.data.commentaire || '');
      }
    });
  }, [profId, user]);

  useEffect(() => {
    if (tab === 'avis') loadAvis();
    if (tab === 'disponibilites' || step === 'choix_dispo') {
      api.get(`/api/professeurs/${profId}/disponibilites`)
        .then(r => setDispos(r.data || []))
        .catch(() => setDispos([]));
    }
  }, [tab, step, profId, loadAvis]);

  /* ── Réservation ── */
  const getModeEffectif = () => {
    if (selectedDispo?.mode_seance && selectedDispo.mode_seance !== 'les_deux') return selectedDispo.mode_seance;
    if (profMode === 'les_deux') return modeChoisi;
    return profMode;
  };

  const getTarif = () => {
    const m = getModeEffectif();
    if (m === 'en_ligne')   return prof.tarif_en_ligne;
    if (m === 'presentiel') return prof.tarif_presentiel;
    return null;
  };

  const needsModeChoice = profMode === 'les_deux' && (!selectedDispo?.mode_seance || selectedDispo.mode_seance === 'les_deux');
  const canReserver     = selectedDispo && (!needsModeChoice || modeChoisi);

  const handleReserver = () => {
    const modeEff = getModeEffectif();
    if (!modeEff) { alert('Choisissez un mode de cours'); return; }
    setSubmitting(true);
    api.post('/api/reservations/', {
      prof_id:          profId,
      disponibilite_id: selectedDispo.id,
      date_cours:       selectedDispo.date_specifique,
      heure_debut:      selectedDispo.heure_debut,
      heure_fin:        selectedDispo.heure_fin,
      mode_seance:      modeEff,
      notes_etudiant:   notes,
    }).then(res => {
      setReservationFaite(res.data);
      setStep('confirmation');
    }).catch(e => {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
    }).finally(() => setSubmitting(false));
  };

  /* ── Soumettre avis ── */
  const handleSubmitAvis = async () => {
    if (!noteForm) { alert('Choisissez une note'); return; }
    setSendingAvis(true);
    try {
      await api.post('/api/avis/', { prof_id: profId, note: noteForm, commentaire: commentForm });
      setAvisSuccess(true);
      setTimeout(() => setAvisSuccess(false), 3000);
      loadAvis();
    } catch (e) {
      alert(e.response?.data?.detail || 'Erreur lors de l\'envoi de l\'avis');
    } finally {
      setSendingAvis(false);
    }
  };

  const disponibles = dispos.filter(d => d.nb_inscrits < d.nb_max_etudiants);
  const complets    = dispos.filter(d => d.nb_inscrits >= d.nb_max_etudiants);

  const TABS = [
    { key: 'profil',         icon: '👤', label: 'Profil'         },
    { key: 'disponibilites', icon: '📅', label: 'Disponibilités' },
    { key: 'avis',           icon: '⭐', label: `Avis (${prof.nb_avis || 0})` },
  ];

  /* ════════ VUE CONFIRMATION ════════ */
  if (step === 'confirmation' && reservationFaite) {
    const isOnline = reservationFaite.mode_seance === 'en_ligne';
    return (
      <ModalOverlay onClose={onClose}>
        <div style={{ padding: 40, textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 16 }}>
          <div style={{ width: 80, height: 80, borderRadius: '50%', background: 'linear-gradient(135deg,#43e97b,#38f9d7)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '2rem', boxShadow: '0 12px 40px rgba(67,233,123,0.4)', animation: 'popIn .4s cubic-bezier(.34,1.56,.64,1)' }}>
            🎉
          </div>
          <style>{`@keyframes popIn{from{transform:scale(0)}to{transform:scale(1)}}`}</style>
          <div>
            <h2 style={{ fontFamily:'Syne', fontSize:'1.5rem', margin:'0 0 6px' }}>Réservation envoyée !</h2>
            <p style={{ color:'var(--text2)', fontSize:'.9rem', margin:0 }}>
              Votre demande a été transmise à <strong style={{ color:'var(--text)' }}>{profNom}</strong>.<br />
              Vous serez notifié dès sa réponse.
            </p>
          </div>

          <div style={{ width:'100%', background:'var(--surface2)', borderRadius:16, padding:20, display:'flex', flexDirection:'column', gap:10 }}>
            {[
              ['📆', 'Date', fmt(reservationFaite.date_cours)],
              ['🕒', 'Horaire', `${reservationFaite.heure_debut?.slice(0,5)} → ${reservationFaite.heure_fin?.slice(0,5)}`],
              ['📡', 'Mode', isOnline ? '🌐 En ligne' : '🏫 Présentiel'],
              ...(getTarif() ? [['💰', 'Tarif', `${getTarif()} DT/h`]] : []),
            ].map(([icon, label, val]) => (
              <div key={label} style={{ display:'flex', justifyContent:'space-between', fontSize:'.88rem' }}>
                <span style={{ color:'var(--text2)' }}>{icon} {label}</span>
                <span style={{ fontWeight:700 }}>{val}</span>
              </div>
            ))}
            {isOnline && (
              <div style={{ marginTop: 6, padding:'10px 14px', background:'rgba(56,189,248,0.1)', border:'1px solid rgba(56,189,248,0.25)', borderRadius:10, fontSize:'.82rem', color:'#38bdf8' }}>
                🎥 Un lien Google Meet vous sera communiqué par le professeur.
              </div>
            )}
          </div>

          <div style={{ display:'flex', gap:10, width:'100%' }}>
            <button onClick={onClose} style={{ flex:1, padding:'13px', background:'var(--surface2)', border:'1px solid var(--border)', borderRadius:12, fontWeight:600, cursor:'pointer', color:'var(--text)' }}>
              Fermer
            </button>
            <button onClick={() => { setStep(null); setSelectedDispo(null); setModeChoisi(null); setTab('disponibilites'); }} style={{ flex:2, padding:'13px', background:'linear-gradient(135deg,#6c63ff,#8b5cf6)', border:'none', borderRadius:12, fontWeight:700, cursor:'pointer', color:'#fff' }}>
              Voir mes réservations
            </button>
          </div>
        </div>
      </ModalOverlay>
    );
  }

  return (
    <ModalOverlay onClose={onClose}>
      {/* ── HERO HEADER ── */}
      <div style={{ position:'relative', flexShrink:0 }}>
        {/* Bandeau gradient */}
        <div style={{ height: 140, background: 'linear-gradient(135deg,rgba(108,99,255,0.6),rgba(255,101,132,0.4))', position:'relative', overflow:'hidden' }}>
          {/* Cercles décoratifs */}
          <div style={{ position:'absolute', width:200, height:200, borderRadius:'50%', background:'rgba(255,255,255,0.04)', top:-60, right:-40 }} />
          <div style={{ position:'absolute', width:120, height:120, borderRadius:'50%', background:'rgba(255,255,255,0.03)', bottom:-30, left:100 }} />
          <button onClick={onClose} style={{ position:'absolute', top:14, right:14, width:34, height:34, borderRadius:10, background:'rgba(0,0,0,0.3)', border:'1px solid rgba(255,255,255,0.15)', cursor:'pointer', color:'#fff', fontSize:'1rem', display:'flex', alignItems:'center', justifyContent:'center', backdropFilter:'blur(4px)' }}>✕</button>
        </div>

        {/* Avatar + infos */}
        <div style={{ padding:'0 28px 20px', marginTop:-56, display:'flex', alignItems:'flex-end', gap:20 }}>
          <div style={{ width:90, height:90, borderRadius:'50%', border:'4px solid var(--surface)', background:'linear-gradient(135deg,#6c63ff,#ff6584)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:'2rem', overflow:'hidden', flexShrink:0, boxShadow:'0 8px 30px rgba(0,0,0,0.4)' }}>
            {prof.photo_url
              ? <img src={`http://localhost:8001${prof.photo_url}`} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }} />
              : '👨‍🏫'}
          </div>
          <div style={{ flex:1, paddingBottom:4 }}>
            <h2 style={{ fontFamily:'Syne', fontSize:'1.35rem', margin:'0 0 6px', color:'var(--text)' }}>{profNom}</h2>
            <div style={{ display:'flex', flexWrap:'wrap', alignItems:'center', gap:8 }}>
              <ModeBadge mode={profMode} />
              {prof.ville && <span style={{ fontSize:'.78rem', color:'var(--text2)' }}>📍 {prof.ville}</span>}
              <div style={{ display:'flex', alignItems:'center', gap:4 }}>
                <Stars value={prof.note_moyenne} size={14} />
                <span style={{ fontSize:'.78rem', color:'var(--text2)' }}>({prof.nb_avis || 0} avis)</span>
              </div>
            </div>
          </div>

          {/* Tarifs en haut à droite */}
          {(prof.tarif_en_ligne || prof.tarif_presentiel) && (
            <div style={{ display:'flex', gap:8, paddingBottom:8, flexShrink:0 }}>
              {prof.tarif_en_ligne && parseFloat(prof.tarif_en_ligne) > 0 && (
                <div style={{ textAlign:'center', padding:'8px 12px', background:'rgba(56,189,248,0.1)', border:'1px solid rgba(56,189,248,0.2)', borderRadius:12 }}>
                  <div style={{ fontSize:'.65rem', color:'#38bdf8', marginBottom:2 }}>🌐 En ligne</div>
                  <div style={{ fontFamily:'Syne', fontWeight:800, color:'#38bdf8', fontSize:'1rem' }}>{prof.tarif_en_ligne} DT</div>
                  <div style={{ fontSize:'.6rem', color:'var(--text2)' }}>/heure</div>
                </div>
              )}
              {prof.tarif_presentiel && parseFloat(prof.tarif_presentiel) > 0 && (
                <div style={{ textAlign:'center', padding:'8px 12px', background:'rgba(67,233,123,0.1)', border:'1px solid rgba(67,233,123,0.2)', borderRadius:12 }}>
                  <div style={{ fontSize:'.65rem', color:'#43e97b', marginBottom:2 }}>🏫 Présentiel</div>
                  <div style={{ fontFamily:'Syne', fontWeight:800, color:'#43e97b', fontSize:'1rem' }}>{prof.tarif_presentiel} DT</div>
                  <div style={{ fontSize:'.6rem', color:'var(--text2)' }}>/heure</div>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Onglets */}
        <div style={{ display:'flex', borderBottom:'1px solid var(--border)', padding:'0 20px', gap:4 }}>
          {TABS.map(t => (
            <button
              key={t.key}
              onClick={() => { setTab(t.key); setStep(null); }}
              style={{ padding:'10px 16px', background:'none', border:'none', cursor:'pointer', fontWeight:600, fontSize:'.82rem', color: tab === t.key ? '#6c63ff' : 'var(--text2)', borderBottom: tab === t.key ? '2px solid #6c63ff' : '2px solid transparent', transition:'all .2s', display:'flex', alignItems:'center', gap:6 }}
            >
              {t.icon} {t.label}
            </button>
          ))}
        </div>
      </div>

      {/* ── CONTENU SCROLLABLE ── */}
      <div style={{ overflowY:'auto', flex:1, padding:'24px 28px' }}>

        {/* ════ ONGLET PROFIL ════ */}
        {tab === 'profil' && (
          <div style={{ display:'flex', flexDirection:'column', gap:20 }}>

            {/* Bio */}
            {prof.bio && (
              <div style={{ background:'var(--surface2)', borderRadius:16, padding:18 }}>
                <div style={{ fontSize:'.72rem', fontWeight:800, color:'var(--text2)', textTransform:'uppercase', letterSpacing:'.08em', marginBottom:10 }}>📝 À propos</div>
                <p style={{ margin:0, fontSize:'.88rem', color:'var(--text)', lineHeight:1.75, borderLeft:'3px solid #6c63ff', paddingLeft:14 }}>{prof.bio}</p>
              </div>
            )}

            {/* Matières */}
            {prof.tarifs_matieres && prof.tarifs_matieres.length > 0 && (
              <div style={{ background:'var(--surface2)', borderRadius:16, padding:18 }}>
                <div style={{ fontSize:'.72rem', fontWeight:800, color:'var(--text2)', textTransform:'uppercase', letterSpacing:'.08em', marginBottom:12 }}>📚 Matières enseignées</div>
                <div style={{ display:'flex', flexWrap:'wrap', gap:8 }}>
                  {[...new Set(prof.tarifs_matieres.map(t => t.nom_matiere))].map(m => (
                    <span key={m} style={{ padding:'5px 13px', background:'rgba(108,99,255,0.1)', border:'1px solid rgba(108,99,255,0.25)', borderRadius:20, fontSize:'.82rem', fontWeight:600, color:'#6c63ff' }}>{m}</span>
                  ))}
                </div>
              </div>
            )}

            {/* Niveaux */}
            {prof.niveaux && prof.niveaux.length > 0 && (
              <div style={{ background:'var(--surface2)', borderRadius:16, padding:18 }}>
                <div style={{ fontSize:'.72rem', fontWeight:800, color:'var(--text2)', textTransform:'uppercase', letterSpacing:'.08em', marginBottom:12 }}>🎓 Niveaux couverts</div>
                <div style={{ display:'flex', flexWrap:'wrap', gap:8 }}>
                  {prof.niveaux.map(n => (
                    <span key={n} style={{ padding:'5px 13px', background:'var(--card)', border:'1px solid var(--border)', borderRadius:20, fontSize:'.82rem', color:'var(--text2)' }}>{n}</span>
                  ))}
                </div>
              </div>
            )}

            {/* Diplômes */}
            {prof.certificats && prof.certificats.length > 0 && (
              <div style={{ background:'var(--surface2)', borderRadius:16, padding:18 }}>
                <div style={{ fontSize:'.72rem', fontWeight:800, color:'var(--text2)', textTransform:'uppercase', letterSpacing:'.08em', marginBottom:12 }}>📜 Diplômes & Certificats</div>
                <div style={{ display:'flex', flexDirection:'column', gap:8 }}>
                  {prof.certificats.map(c => (
                    <a key={c.id} href={`http://localhost:8001${c.fichier_url}`} target="_blank" rel="noreferrer" style={{ textDecoration:'none', display:'flex', alignItems:'center', gap:12, padding:'10px 14px', background:'var(--card)', border:'1px solid rgba(108,99,255,0.2)', borderRadius:11, transition:'all .15s' }}
                      onMouseEnter={e => { e.currentTarget.style.borderColor='rgba(108,99,255,0.5)'; e.currentTarget.style.background='rgba(108,99,255,0.06)'; }}
                      onMouseLeave={e => { e.currentTarget.style.borderColor='rgba(108,99,255,0.2)'; e.currentTarget.style.background='var(--card)'; }}
                    >
                      <span style={{ fontSize:'1.3rem' }}>{c.fichier_url?.endsWith('.pdf') ? '📄' : '🖼️'}</span>
                      <span style={{ fontWeight:600, fontSize:'.85rem', flex:1, color:'var(--text)' }}>{c.titre}</span>
                      <span style={{ fontSize:'.75rem', color:'#6c63ff', fontWeight:600 }}>Consulter ↗</span>
                    </a>
                  ))}
                </div>
              </div>
            )}

            {/* Bouton réserver */}
            {user?.role === 'étudiant' && (
              <button
                onClick={() => { setTab('disponibilites'); setStep('choix_dispo'); }}
                style={{ width:'100%', padding:'15px', background:'linear-gradient(135deg,#6c63ff,#8b5cf6)', border:'none', borderRadius:14, fontWeight:700, fontSize:'1rem', cursor:'pointer', color:'#fff', boxShadow:'0 6px 20px rgba(108,99,255,0.4)', transition:'transform .15s' }}
                onMouseEnter={e => e.currentTarget.style.transform='translateY(-2px)'}
                onMouseLeave={e => e.currentTarget.style.transform='translateY(0)'}
              >
                📅 Réserver un cours
              </button>
            )}
          </div>
        )}

        {/* ════ ONGLET DISPONIBILITÉS ════ */}
        {tab === 'disponibilites' && (
          <div style={{ display:'flex', flexDirection:'column', gap:16 }}>

            {/* Étape : choisir dispo */}
            {step !== 'recapitulatif' && (
              <>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                  <div style={{ fontWeight:700, fontSize:'.95rem' }}>
                    {disponibles.length > 0 ? `${disponibles.length} créneau${disponibles.length > 1 ? 'x' : ''} disponible${disponibles.length > 1 ? 's' : ''}` : 'Aucun créneau disponible'}
                  </div>
                  {user?.role === 'étudiant' && selectedDispo && (
                    <button
                      onClick={() => { setStep('recapitulatif'); }}
                      style={{ padding:'8px 18px', background:'linear-gradient(135deg,#6c63ff,#8b5cf6)', border:'none', borderRadius:10, fontWeight:700, cursor:'pointer', color:'#fff', fontSize:'.85rem' }}
                    >
                      Confirmer →
                    </button>
                  )}
                </div>

                {disponibles.length === 0 && complets.length === 0 && (
                  <div style={{ textAlign:'center', padding:'40px 20px', background:'var(--surface2)', borderRadius:16, color:'var(--text2)' }}>
                    <div style={{ fontSize:'2rem', marginBottom:10 }}>📭</div>
                    <div style={{ fontWeight:600, marginBottom:6 }}>Aucune disponibilité planifiée</div>
                    <div style={{ fontSize:'.82rem' }}>Ce professeur n'a pas encore ajouté de créneaux.</div>
                  </div>
                )}

                {/* Créneaux disponibles */}
                {disponibles.map(d => {
                  const isSelected = selectedDispo?.id === d.id;
                  const pct = Math.round((d.nb_inscrits / d.nb_max_etudiants) * 100);
                  return (
                    <div
                      key={d.id}
                      onClick={() => { if (user?.role === 'étudiant') setSelectedDispo(isSelected ? null : d); }}
                      style={{ padding:'16px 18px', background: isSelected ? 'rgba(108,99,255,0.1)' : 'var(--surface2)', border: isSelected ? '2px solid #6c63ff' : '2px solid var(--border)', borderRadius:16, cursor: user?.role === 'étudiant' ? 'pointer' : 'default', transition:'all .2s', boxShadow: isSelected ? '0 4px 20px rgba(108,99,255,0.2)' : 'none' }}
                    >
                      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
                        <div>
                          <div style={{ fontWeight:700, fontSize:'.95rem', marginBottom:4, display:'flex', alignItems:'center', gap:8 }}>
                            {isSelected && <span style={{ width:8, height:8, borderRadius:'50%', background:'#6c63ff', display:'inline-block' }} />}
                            📅 {fmt(d.date_specifique)}
                          </div>
                          <div style={{ fontSize:'.83rem', color:'#6c63ff', fontWeight:600 }}>
                            🕒 {d.heure_debut?.slice(0,5)} → {d.heure_fin?.slice(0,5)}
                          </div>
                        </div>
                        <div style={{ textAlign:'right' }}>
                          <div style={{ display:'flex', gap:6, justifyContent:'flex-end', marginBottom:6 }}>
                            <span style={{ fontSize:'.7rem', fontWeight:600, padding:'2px 8px', borderRadius:20, background: d.mode_seance === 'en_ligne' ? 'rgba(56,189,248,0.12)' : 'rgba(67,233,123,0.12)', color: d.mode_seance === 'en_ligne' ? '#38bdf8' : '#43e97b' }}>
                              {d.mode_seance === 'en_ligne' ? '🌐 En ligne' : '🏫 Présentiel'}
                            </span>
                          </div>
                          <div style={{ fontSize:'.75rem', color:'var(--text2)' }}>
                            👥 {d.nb_inscrits}/{d.nb_max_etudiants} inscrits
                          </div>
                        </div>
                      </div>

                      {/* Barre de remplissage */}
                      <div style={{ marginTop:12, height:4, background:'var(--border)', borderRadius:4, overflow:'hidden' }}>
                        <div style={{ height:'100%', borderRadius:4, width:`${pct}%`, background: pct >= 80 ? '#f59e0b' : '#43e97b', transition:'width .3s' }} />
                      </div>
                    </div>
                  );
                })}

                {/* Créneaux complets */}
                {complets.length > 0 && (
                  <>
                    <div style={{ fontSize:'.78rem', fontWeight:700, color:'var(--text2)', textTransform:'uppercase', letterSpacing:'.07em' }}>Créneaux complets</div>
                    {complets.map(d => (
                      <div key={d.id} style={{ padding:'14px 18px', background:'var(--surface2)', border:'1px solid var(--border)', borderRadius:14, opacity:.6 }}>
                        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                          <div>
                            <div style={{ fontWeight:600, fontSize:'.9rem', marginBottom:3 }}>📅 {fmt(d.date_specifique)}</div>
                            <div style={{ fontSize:'.8rem', color:'var(--text2)' }}>🕒 {d.heure_debut?.slice(0,5)} → {d.heure_fin?.slice(0,5)}</div>
                          </div>
                          <span style={{ fontSize:'.75rem', fontWeight:700, color:'#ff6584', padding:'3px 10px', borderRadius:20, background:'rgba(255,101,132,0.1)' }}>🔴 Complet</span>
                        </div>
                      </div>
                    ))}
                  </>
                )}
              </>
            )}

            {/* Étape : récap + confirmation */}
            {step === 'recapitulatif' && selectedDispo && (
              <div style={{ display:'flex', flexDirection:'column', gap:14 }}>
                <button onClick={() => setStep(null)} style={{ display:'flex', alignItems:'center', gap:6, background:'none', border:'none', color:'var(--text2)', cursor:'pointer', fontSize:'.85rem', padding:0, alignSelf:'flex-start' }}>
                  ← Retour aux créneaux
                </button>

                <div style={{ padding:'16px 18px', background:'rgba(108,99,255,0.08)', border:'2px solid rgba(108,99,255,0.3)', borderRadius:16 }}>
                  <div style={{ fontWeight:800, color:'#6c63ff', marginBottom:10, fontSize:'.85rem' }}>📋 Créneau sélectionné</div>
                  <div style={{ display:'flex', flexDirection:'column', gap:6, fontSize:'.88rem' }}>
                    <div>📅 <strong>{fmt(selectedDispo.date_specifique)}</strong></div>
                    <div>🕒 <strong>{selectedDispo.heure_debut?.slice(0,5)} → {selectedDispo.heure_fin?.slice(0,5)}</strong></div>
                    <div>👥 <strong>{selectedDispo.nb_inscrits}/{selectedDispo.nb_max_etudiants}</strong> inscrits</div>
                  </div>
                </div>

                {/* Choix mode si les_deux */}
                {needsModeChoice && (
                  <div>
                    <div style={{ fontSize:'.78rem', fontWeight:700, color:'var(--text2)', marginBottom:10, textTransform:'uppercase', letterSpacing:'.07em' }}>Choisissez votre mode</div>
                    <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:10 }}>
                      {[
                        { value:'en_ligne',   icon:'🌐', label:'En ligne',   tarif: prof.tarif_en_ligne,   color:'#38bdf8', bg:'rgba(56,189,248,0.1)',  border:'rgba(56,189,248,0.4)'  },
                        { value:'presentiel', icon:'🏫', label:'Présentiel', tarif: prof.tarif_presentiel, color:'#43e97b', bg:'rgba(67,233,123,0.1)',  border:'rgba(67,233,123,0.4)'  },
                      ].map(m => {
                        const active = modeChoisi === m.value;
                        return (
                          <div key={m.value} onClick={() => setModeChoisi(m.value)}
                            style={{ padding:14, borderRadius:12, cursor:'pointer', border: active ? `2px solid ${m.color}` : '2px solid var(--border)', background: active ? m.bg : 'var(--surface2)', transition:'all .15s', textAlign:'center' }}
                          >
                            <div style={{ fontSize:'1.6rem', marginBottom:6 }}>{m.icon}</div>
                            <div style={{ fontWeight:700, color: active ? m.color : 'var(--text)', fontSize:'.9rem' }}>{m.label}</div>
                            {m.tarif && <div style={{ fontSize:'.78rem', color: active ? m.color : 'var(--text2)', marginTop:4, fontWeight:600 }}>{m.tarif} DT/h</div>}
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )}

                {/* Mode fixe */}
                {!needsModeChoice && (
                  <div style={{ padding:'12px 16px', background: selectedDispo.mode_seance === 'en_ligne' ? 'rgba(56,189,248,0.08)' : 'rgba(67,233,123,0.08)', border:`1px solid ${selectedDispo.mode_seance === 'en_ligne' ? 'rgba(56,189,248,0.3)' : 'rgba(67,233,123,0.3)'}`, borderRadius:12, display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                    <span style={{ fontWeight:700, color: selectedDispo.mode_seance === 'en_ligne' ? '#38bdf8' : '#43e97b' }}>
                      {selectedDispo.mode_seance === 'en_ligne' ? '🌐 En ligne' : '🏫 Présentiel'}
                    </span>
                    {getTarif() && <span style={{ fontWeight:800, fontSize:'1.1rem', color: selectedDispo.mode_seance === 'en_ligne' ? '#38bdf8' : '#43e97b' }}>{getTarif()} DT/h</span>}
                  </div>
                )}

                {getModeEffectif() === 'en_ligne' && (
                  <div style={{ padding:'10px 14px', background:'rgba(56,189,248,0.07)', border:'1px solid rgba(56,189,248,0.2)', borderRadius:10, fontSize:'.8rem', color:'#38bdf8', display:'flex', gap:8 }}>
                    🎥 Un lien Google Meet sera partagé automatiquement.
                  </div>
                )}

                <div>
                  <div style={{ fontSize:'.76rem', fontWeight:700, color:'var(--text2)', marginBottom:6, textTransform:'uppercase', letterSpacing:'.07em' }}>Message pour le professeur (optionnel)</div>
                  <textarea
                    rows={3}
                    value={notes}
                    onChange={e => setNotes(e.target.value)}
                    placeholder="Ex: Je prépare le bac, j'ai des difficultés en algèbre..."
                    style={{ background:'var(--surface2)', border:'1px solid var(--border)', borderRadius:10, color:'var(--text)', padding:'10px 13px', width:'100%', outline:'none', fontSize:'.86rem', resize:'vertical', boxSizing:'border-box' }}
                  />
                </div>

                <button
                  onClick={handleReserver}
                  disabled={!canReserver || submitting}
                  style={{ width:'100%', padding:'15px', background: !canReserver || submitting ? 'var(--border)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border:'none', borderRadius:14, fontWeight:700, fontSize:'.95rem', cursor: !canReserver || submitting ? 'not-allowed' : 'pointer', color:'#fff', transition:'all .2s', boxShadow: canReserver ? '0 6px 20px rgba(108,99,255,0.35)' : 'none' }}
                >
                  {submitting ? '⏳ Envoi en cours...' : '✅ Confirmer la réservation'}
                </button>
              </div>
            )}
          </div>
        )}

        {/* ════ ONGLET AVIS ════ */}
        {tab === 'avis' && (
          <div style={{ display:'flex', flexDirection:'column', gap:20 }}>

            {/* Stats globales */}
            {avisStats && (
              <div style={{ background:'var(--surface2)', borderRadius:18, padding:20, display:'flex', gap:24, alignItems:'center' }}>
                <div style={{ textAlign:'center', flexShrink:0 }}>
                  <div style={{ fontFamily:'Syne', fontSize:'3rem', fontWeight:800, lineHeight:1, color:'var(--text)' }}>
                    {avisStats.moyenne.toFixed(1)}
                  </div>
                  <Stars value={avisStats.moyenne} size={18} />
                  <div style={{ fontSize:'.75rem', color:'var(--text2)', marginTop:6 }}>{avisStats.total} avis</div>
                </div>
                <div style={{ flex:1 }}>
                  {[5,4,3,2,1].map(s => {
                    const count = avisStats.distribution[s] || 0;
                    const pct   = avisStats.total > 0 ? Math.round((count / avisStats.total) * 100) : 0;
                    return (
                      <div key={s} style={{ display:'flex', alignItems:'center', gap:8, marginBottom:5 }}>
                        <span style={{ fontSize:'.72rem', color:'var(--text2)', width:18, textAlign:'right', flexShrink:0 }}>{s}</span>
                        <span style={{ color:'#f59e0b', fontSize:'.8rem' }}>★</span>
                        <div style={{ flex:1, height:6, background:'var(--border)', borderRadius:4, overflow:'hidden' }}>
                          <div style={{ height:'100%', borderRadius:4, background:'linear-gradient(90deg,#f59e0b,#fbbf24)', width:`${pct}%`, transition:'width .6s ease' }} />
                        </div>
                        <span style={{ fontSize:'.72rem', color:'var(--text2)', width:28, flexShrink:0 }}>{count}</span>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {/* Formulaire avis étudiant */}
            {user?.role === 'étudiant' && (
              <div style={{ background:'var(--surface2)', borderRadius:18, padding:20, border:'1px solid var(--border)' }}>
                <div style={{ fontSize:'.78rem', fontWeight:800, color:'var(--text2)', textTransform:'uppercase', letterSpacing:'.08em', marginBottom:14 }}>
                  {monAvis ? '✏️ Modifier mon avis' : '✍️ Laisser un avis'}
                </div>

                <div style={{ marginBottom:14 }}>
                  <div style={{ fontSize:'.82rem', color:'var(--text2)', marginBottom:8 }}>Ma note</div>
                  <Stars value={noteForm} size={28} interactive onChange={setNoteForm} />
                  {noteForm > 0 && (
                    <div style={{ marginTop:6, fontSize:'.8rem', color:'#f59e0b', fontWeight:600 }}>
                      {['', 'Décevant 😕', 'Passable 😐', 'Bien 🙂', 'Très bien 😊', 'Excellent 🌟'][noteForm]}
                    </div>
                  )}
                </div>

                <textarea
                  rows={3}
                  value={commentForm}
                  onChange={e => setCommentForm(e.target.value)}
                  placeholder="Partagez votre expérience avec ce professeur... (optionnel)"
                  style={{ background:'var(--card)', border:'1px solid var(--border)', borderRadius:10, color:'var(--text)', padding:'10px 13px', width:'100%', outline:'none', fontSize:'.86rem', resize:'vertical', boxSizing:'border-box', marginBottom:12 }}
                />

                <button
                  onClick={handleSubmitAvis}
                  disabled={!noteForm || sendingAvis}
                  style={{ width:'100%', padding:'12px', background: avisSuccess ? 'linear-gradient(135deg,#43e97b,#38f9d7)' : !noteForm || sendingAvis ? 'var(--border)' : 'linear-gradient(135deg,#f59e0b,#f97316)', border:'none', borderRadius:11, fontWeight:700, cursor: !noteForm || sendingAvis ? 'not-allowed' : 'pointer', color: avisSuccess ? '#000' : '#fff', fontSize:'.88rem', transition:'all .3s' }}
                >
                  {avisSuccess ? '✅ Avis publié !' : sendingAvis ? '⏳ Envoi...' : monAvis ? '💾 Mettre à jour mon avis' : '⭐ Publier mon avis'}
                </button>

                {!monAvis && (
                  <div style={{ marginTop:10, fontSize:'.75rem', color:'var(--text2)', textAlign:'center' }}>
                    ℹ️ Vous devez avoir eu un cours confirmé avec ce professeur pour pouvoir laisser un avis.
                  </div>
                )}
              </div>
            )}

            {/* Liste des avis */}
            {avis.length === 0 ? (
              <div style={{ textAlign:'center', padding:'32px 20px', background:'var(--surface2)', borderRadius:16, color:'var(--text2)' }}>
                <div style={{ fontSize:'2rem', marginBottom:10 }}>💬</div>
                <div style={{ fontWeight:600 }}>Aucun avis pour ce professeur</div>
                <div style={{ fontSize:'.82rem', marginTop:4 }}>Soyez le premier à partager votre expérience !</div>
              </div>
            ) : (
              <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
                {avis.map(a => (
                  <div key={a.id} style={{ background:'var(--surface2)', borderRadius:14, padding:16, border:'1px solid var(--border)' }}>
                    <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:10 }}>
                      <div style={{ display:'flex', alignItems:'center', gap:10 }}>
                        <div style={{ width:36, height:36, borderRadius:'50%', background:'linear-gradient(135deg,#6c63ff,#ff6584)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:'.9rem', fontWeight:700, color:'#fff', flexShrink:0 }}>
                          {(a.etudiant || 'A')[0].toUpperCase()}
                        </div>
                        <div>
                          <div style={{ fontWeight:700, fontSize:'.88rem' }}>{a.etudiant}</div>
                          {a.created_at && (
                            <div style={{ fontSize:'.7rem', color:'var(--text2)' }}>
                              {new Date(a.created_at).toLocaleDateString('fr-FR', { day:'numeric', month:'short', year:'numeric' })}
                            </div>
                          )}
                        </div>
                      </div>
                      <div style={{ display:'flex', flexDirection:'column', alignItems:'flex-end', gap:3 }}>
                        <Stars value={a.note} size={14} />
                        {monAvis?.id === a.id && (
                          <span style={{ fontSize:'.65rem', color:'#6c63ff', fontWeight:700, background:'rgba(108,99,255,0.1)', padding:'1px 7px', borderRadius:20 }}>Mon avis</span>
                        )}
                      </div>
                    </div>
                    {a.commentaire && (
                      <p style={{ margin:0, fontSize:'.85rem', color:'var(--text)', lineHeight:1.65 }}>{a.commentaire}</p>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </ModalOverlay>
  );
}
